import os,re,glob,time,datetime,collections
now=time.time()
fs=[f for d in ('Notes','Knowledge','Projects') for f in glob.glob(f'{d}/**/*.md',recursive=True)]
print('notes scanned',len(fs))
seeds=[]
for f in fs:
    t=open(f,errors='ignore').read(3000)
    if re.search(r'^status:\s*seed',t,re.M):
        age=(now-os.path.getmtime(f))/86400
        if age>60: seeds.append((int(age),f))
seeds.sort(reverse=True); print('stale seeds >60d:',len(seeds),'oldest',seeds[:3])
proj=[]
for f in fs:
    b=os.path.basename(f)
    if b.startswith('Project_'):
        age=(now-os.path.getmtime(f))/86400; t=open(f,errors='ignore').read(2000)
        if age>30 and re.search(r'status:\s*(active|in.progress)',t,re.I): proj.append((int(age),f))
print('stale active Project_*:',proj)
sl=collections.defaultdict(list)
for f in fs: sl[os.path.basename(f).lower()].append(f)
print('slug dupes:',{k:len(v) for k,v in sl.items() if len(v)>1})
newest=max(os.path.getmtime(f) for f in glob.glob('Notes/**/*.md',recursive=True))
print('Notes newest',datetime.date.fromtimestamp(newest))
# near-dup titles
def words(f): return set(re.findall(r'[a-z0-9]+',os.path.basename(f).lower()[:-3]))-{'the','and','of','a','to','in','for','is','vs','md'}
items=[(f,words(f)) for f in fs if not os.path.basename(f).startswith(('_','README'))]
pairs=[]
for i in range(len(items)):
    for j in range(i+1,len(items)):
        a,b=items[i][1],items[j][1]
        if len(a)>=3 and len(b)>=3:
            jac=len(a&b)/len(a|b)
            if jac>=0.6: pairs.append((round(jac,2),items[i][0],items[j][0]))
pairs.sort(reverse=True); print('near-dup title pairs:',len(pairs))
for p in pairs[:15]: print(' ',p)
EOF

