import os,re,glob,collections
H=os.path.expanduser('~')
dirs=sorted(glob.glob(f'{H}/.claude/projects/*/memory'))
tot=0;broken=[];unindexed=[];multi=[];noidx=[]
for d in dirs:
    files={os.path.basename(f) for f in glob.glob(f'{d}/*.md')}-{'MEMORY.md'}
    tot+=len(files)
    idx=f'{d}/MEMORY.md'
    if not os.path.exists(idx):
        if files: noidx.append((d.replace(H,'~'),len(files)))
        continue
    t=open(idx,errors='ignore').read()
    links=re.findall(r'\]\(([^)]+\.md)\)',t)
    c=collections.Counter(os.path.basename(l) for l in links)
    for l in set(links):
        if not os.path.exists(os.path.join(d,l)): broken.append((d.replace(H,'~'),l))
    for f in files:
        if c[f]==0: unindexed.append((d.replace(H,'~'),f))
        elif c[f]>1: multi.append((d.replace(H,'~'),f,c[f]))
print('folders',len(dirs),'files',tot)
print('broken',len(broken)); [print(' ',*b) for b in broken]
print('unindexed',len(unindexed)); [print(' ',*u) for u in unindexed]
print('multi',len(multi)); [print(' ',*m) for m in multi]
print('no MEMORY.md but files',noidx)
EOF

